<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Reports;use Acorn\SafetyHealthcheck\Assessment\{AssessmentRepository,ContactRepository};final class ReportDataBuilder{private const MAP=['fire'=>'fire','legionella'=>'legionella','asbestos'=>'asbestos','management'=>'health_safety','risk'=>'health_safety','people'=>'health_safety','incidents'=>'health_safety','workplace'=>'health_safety','specialist'=>'health_safety'];public function build(int$id):array{$a=(new AssessmentRepository)->find($id);$s=json_decode($a['snapshot_json'],true);$c=(new ContactRepository)->find((int)$a['contact_id']);$groups=['addressed'=>[],'review'=>[],'priority'=>[]];$pill=[];$rank=['addressed'=>1,'review'=>2,'priority'=>3];foreach($s['findings']as$f){$groups[$f['finding_status']][]=$f;$p=self::MAP[$f['module_key']];if(!isset($pill[$p])||$rank[$f['finding_status']]>$rank[$pill[$p]])$pill[$p]=$f['finding_status'];}foreach($groups as&$g)usort($g,fn($x,$y)=>$x['sort_rank']<=>$y['sort_rank']);$labels=['health_safety'=>'Health & Safety','fire'=>'Fire Safety','legionella'=>'Legionella','asbestos'=>'Asbestos'];$pillars=[];foreach($labels as$k=>$l)$pillars[]=['key'=>$k,'label'=>$l,'status'=>$pill[$k]??'not_assessed'];return['meta'=>['company'=>$c['company'],'assessment_date'=>substr($a['completed_at'],0,10),'jurisdiction'=>$a['jurisdiction'],'content_version'=>(string)$s['content_version'],'areas_assessed'=>array_sum(array_map('count',$groups))],'summary'=>$s['summary'],'pillars'=>$pillars,'sections'=>['addressed'=>['label'=>'What appears to be working'],'review'=>['label'=>'Things worth checking'],'priority'=>['label'=>'Priority actions']],'addressed'=>$groups['addressed'],'review'=>$groups['review'],'priority'=>$groups['priority'],'action_summary'=>array_merge($groups['priority'],$groups['review']),'disclaimer'=>'This Healthcheck is based on information supplied through an online self-assessment. It is intended to highlight areas that may merit further review and does not constitute a formal audit, legal advice or confirmation of compliance.','support'=>['heading'=>'Need help with any of the actions identified?','cta_label'=>'Request a free Health & Safety Compliance Audit','cta_url'=>(get_option('acorn_hc_settings',[])['audit_cta_url']??'')]];}}
